            # Single-cell terminal gaps can occur in otherwise similar rows
            # with small internal differences; mark only the missing endpoint.
            elif ((a[-1] == bg) != (b[-1] == bg) and
                  sum(x == y for x, y in zip(a, b)) >= 0.6 * w):
                if a[-1] == bg:
                    out[i][-1] = 1
                else:
                    out[j][-1] = 1
    return out
